/**
 * Shared result shapes of vecDSL searches. Generated by vecDSL 7. Do not edit.
 *
 * One implementation of the result-shape clauses (boost, cursor, mmr, group-by with size, sort, offset and limit, score
 * bounds, with-total, aggregate, exclude, with-vectors) over the candidate window a target retrieved, following the pgvector
 * generator's pipeline. The same module exists in Python and
 * Java; equal input gives equal output in the three languages (generator/common/shapes/README.md). No dependencies.
 *
 * A candidate is {key, score, fields, vectors?, highlight?, explanation?}: score is the canonical similarity (higher is
 * better), the native score under `score native`, or null for a scroll, whose records have no score.
 */

export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
type Obj = { [key: string]: Json };

const DIGITS = 6;
const PERCENTS = [1, 5, 25, 50, 75, 95, 99];
const UNITS: Record<string, number> = {
  ms: 0.001, msec: 0.001, msecs: 0.001, millisecond: 0.001, milliseconds: 0.001,
  s: 1, sec: 1, secs: 1, second: 1, seconds: 1,
  m: 60, min: 60, mins: 60, minute: 60, minutes: 60,
  h: 3600, hr: 3600, hrs: 3600, hour: 3600, hours: 3600,
  d: 86400, day: 86400, days: 86400,
  w: 604800, week: 604800, weeks: 604800,
};
const INTERVAL = /\s*([0-9]+(?:\.[0-9]+)?)\s*([A-Za-z]+)/y;
const NUMBER = /^[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?$/;
const TIMESTAMP = /^([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[T ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(\.[0-9]+)?)?)?(Z|z|[+-][0-9]{2}(?::?[0-9]{2})?)?$/;

/** A combination of result-shape clauses the module refuses, with pgvector's reason. */
export class UnsupportedShape extends Error {}

interface Hit {
  key: string | number;
  score: number | null;
  fields: Obj;
  vectors: Obj;
  highlight: Json;
  explanation: Json;
  ord: number;
}

function isNumber(value: unknown): value is number {
  return typeof value === "number";
}

function isObject(value: unknown): value is Obj {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function list(value: Json | undefined): Json[] {
  return Array.isArray(value) ? value : [];
}

function given(value: Json | undefined): value is Exclude<Json, null> {
  return value !== undefined && value !== null;
}

/**
 * Candidates a target retrieves for the spec: the mmr pool when its `candidates` is written, else ten times limit plus offset
 * when a shape clause is written, else limit plus offset; null (every matching record) for a scroll that sorts or resumes after
 * a cursor, or has no limit.
 */
export function windowSize(spec: Obj): number | null {
  const limit = spec.limit;
  const offset = isNumber(spec.offset) ? spec.offset : 0;
  if (!isNumber(limit)) return null;
  if (form(spec) === null) return list(spec.sort).length > 0 || given(spec.cursor) ? null : limit + offset;
  const fetch = limit + offset;
  const mmr = spec.mmr;
  if (isObject(mmr) && isNumber(mmr.candidates)) return Math.max(mmr.candidates, fetch);
  return shaped(spec) ? 10 * fetch : fetch;
}

function shaped(spec: Obj): boolean {
  return given(spec.cursor) || given(spec.boost) || given(spec.mmr) || given(spec.group) || list(spec.sort).length > 0
    || spec.withTotal === true || list(spec.aggregations).length > 0;
}

function form(spec: Obj): string | null {
  return spec.score === undefined ? "similarity" : (spec.score as string | null);
}

/**
 * The result of a search from its candidate window: a list of hits, a list of {group, hits}, or {hits, total, aggregations}
 * when with-total or aggregate is written.
 */
export function shape(candidates: Json[], spec: Obj): Json {
  refuse(spec);
  const scoreForm = form(spec);
  const keyField = typeof spec.keyField === "string" && spec.keyField !== "" ? spec.keyField : "id";
  const offset = isNumber(spec.offset) ? spec.offset : 0;
  const limit = isNumber(spec.limit) ? spec.limit : null;
  const bounds = isObject(spec.bounds) ? spec.bounds : {};
  const clauses = list(spec.sort) as Obj[];
  const hits = toHits(candidates, scoreForm === null);
  let ranked: Hit[];
  if (scoreForm === null) {
    ranked = [...hits].sort((a, b) => byClauses(a, b, clauses) || compareKeys(a.key, b.key));
  } else if (scoreForm === "native") {
    ranked = hits;
  } else {
    ranked = [...hits].sort(byRelevance);
  }
  if (isObject(spec.boost)) {
    boost(ranked, spec.boost);
    ranked.sort(byRelevance);
  }
  ranked.forEach((hit, position) => {
    hit.ord = position;
  });
  const matched = ranked;
  if (given(spec.cursor)) ranked = after(ranked, spec.cursor);
  let result: Json;
  if (isObject(spec.group)) {
    result = groups(ranked, spec, bounds, keyField, offset, limit);
  } else {
    let page = isObject(spec.mmr) ? diverse(ranked, spec.mmr, offset, limit) : ranked.slice(offset, limit === null ? undefined : offset + limit);
    if (scoreForm !== null && clauses.length > 0) {
      page = page.map((hit, position) => ({ hit, position }))
        .sort((a, b) => byClauses(a.hit, b.hit, clauses) || a.position - b.position)
        .map((entry) => entry.hit);
    }
    result = page.filter((hit) => within(hit.score, bounds)).map((hit) => project(hit, spec, keyField));
  }
  const aggregations = list(spec.aggregations) as Obj[];
  if (spec.withTotal === true || aggregations.length > 0) {
    const inside = matched.filter((hit) => within(hit.score, bounds));
    const wrapped: Obj = { hits: result };
    if (spec.withTotal === true) wrapped.total = inside.length;
    if (aggregations.length > 0) {
      const values: Obj = {};
      for (const a of aggregations) values[aggregationName(a)] = aggregate(inside, a);
      wrapped.aggregations = values;
    }
    result = wrapped;
  }
  return value(result);
}

function refuse(spec: Obj): void {
  const scoreForm = form(spec);
  const group = given(spec.group);
  const mmr = given(spec.mmr);
  const boosted = given(spec.boost);
  if (given(spec.cursor) && (group || mmr)) {
    throw new UnsupportedShape("the 'cursor' clause with group-by or mmr; keyset pagination continues after one record in an "
      + "order that each record's own values decide");
  }
  if (group && list(spec.sort).length > 0) throw new UnsupportedShape("sort with group-by; groups follow the relevance of their best hit");
  if (group && mmr) throw new UnsupportedShape("mmr with group-by; MMR selects single hits, groups select records per group value");
  if (boosted && scoreForm === "native") {
    throw new UnsupportedShape("boosts with score native; boosts apply to the canonical similarity, where higher is better");
  }
  if (mmr && scoreForm === "native") {
    throw new UnsupportedShape("mmr with score native; MMR weighs the canonical similarity, which a native score does not give");
  }
  if (scoreForm === null && (boosted || mmr || group)) {
    throw new UnsupportedShape("boost, mmr and group-by on a scroll, whose records have no score");
  }
  if (isObject(spec.mmr)) {
    const lambda = Number(spec.mmr.lambda);
    if (!(lambda >= 0 && lambda <= 1)) throw new UnsupportedShape("an mmr lambda outside 0 to 1");
  }
  if (isObject(spec.boost)) {
    for (const fn of list(spec.boost.functions) as Obj[]) {
      if (fn.kind === "decay" && given(fn.rate) && !(Number(fn.rate) > 0 && Number(fn.rate) < 1)) {
        throw new UnsupportedShape("a decay rate outside the open interval from 0 to 1");
      }
    }
  }
  for (const a of list(spec.aggregations) as Obj[]) {
    if (a.kind === "range") throw new UnsupportedShape("range aggregations; vecDSL gives no range bounds to count records in");
  }
}

function toHits(candidates: Json[], unscored: boolean): Hit[] {
  const hits: Hit[] = [];
  const seen = new Set<string>();
  for (const candidate of candidates) {
    if (!isObject(candidate)) throw new Error("a candidate is not an object");
    const key = candidate.key;
    if (!(typeof key === "string" || isNumber(key) && Number.isFinite(key))) {
      throw new Error(`a candidate key must be a string or a finite number: ${canonical(key ?? null)}`);
    }
    const identity = canonical(key);
    if (seen.has(identity)) throw new Error(`duplicate candidate key ${identity}`);
    seen.add(identity);
    const score = candidate.score ?? null;
    if (score !== null && !(isNumber(score) && Number.isFinite(score))) {
      throw new Error(`the score of candidate ${identity} is not a finite number`);
    }
    if (score === null && !unscored) throw new Error(`candidate ${identity} has no score`);
    const fields = candidate.fields ?? {};
    const vectors = candidate.vectors ?? {};
    if (!isObject(fields) || !isObject(vectors)) throw new Error(`the fields or vectors of candidate ${identity} are not an object`);
    hits.push({ key, score: score as number | null, fields, vectors, highlight: candidate.highlight ?? null,
      explanation: candidate.explanation ?? null, ord: 0 });
  }
  return hits;
}

// ---------------------------------------------------------------- order

/** Strings by code point, as Python compares them. */
function compareText(a: string, b: string): number {
  const x = Array.from(a);
  const y = Array.from(b);
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const d = (x[i].codePointAt(0) as number) - (y[i].codePointAt(0) as number);
    if (d !== 0) return d < 0 ? -1 : 1;
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
}

function sign(a: number, b: number): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Keys: numbers before strings, numbers by value, strings by code point (the runtimes' _order). */
function compareKeys(a: string | number, b: string | number): number {
  if (isNumber(a) !== isNumber(b)) return isNumber(a) ? -1 : 1;
  return isNumber(a) ? sign(a, b as number) : compareText(a, b as string);
}

function byRelevance(a: Hit, b: Hit): number {
  return sign(b.score as number, a.score as number) || compareKeys(a.key, b.key);
}

function rank(value: Json): number {
  if (isNumber(value)) return 0;
  if (typeof value === "string") return 1;
  if (typeof value === "boolean") return 2;
  return 3;
}

/** Field values: numbers, then strings by code point, then booleans, then lists and objects by their JSON text. */
function compareValues(a: Json, b: Json): number {
  const ra = rank(a);
  const rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 0) return sign(a as number, b as number);
  if (ra === 1) return compareText(a as string, b as string);
  if (ra === 2) return sign(Number(a), Number(b));
  return compareText(canonical(a), canonical(b));
}

/** Sort keys: field values with missing values last in both directions, relevance by rank. */
function byClauses(a: Hit, b: Hit, clauses: Obj[]): number {
  for (const clause of clauses) {
    const descending = clause.direction === "desc";
    let result: number;
    if (clause.relevance === true) {
      result = descending ? a.ord - b.ord : b.ord - a.ord;
    } else {
      const field = list(clause.field) as string[];
      const va = path(a.fields, field);
      const vb = path(b.fields, field);
      if (va === null || vb === null) {
        result = (va === null ? 1 : 0) - (vb === null ? 1 : 0);
      } else {
        result = descending ? -compareValues(va, vb) : compareValues(va, vb);
      }
    }
    if (result !== 0) return result;
  }
  return 0;
}

function path(fields: Json, segments: string[]): Json {
  let current: Json = fields;
  for (const segment of segments) {
    current = isObject(current) && Object.prototype.hasOwnProperty.call(current, segment) ? current[segment] : null;
  }
  return current === undefined ? null : current;
}

/**
 * JSON text with numbers as JavaScript prints them and object keys in code point order: the identity of a key, a group value
 * or a term, and the text of values in messages, equal in the three languages.
 */
function canonical(item: Json): string {
  if (item === null) return "null";
  if (typeof item === "boolean") return item ? "true" : "false";
  if (isNumber(item)) return String(item);
  if (typeof item === "string") return JSON.stringify(item);
  if (Array.isArray(item)) return "[" + item.map(canonical).join(",") + "]";
  return "{" + Object.keys(item).sort(compareText).map((k) => JSON.stringify(k) + ":" + canonical(item[k])).join(",") + "}";
}

// ---------------------------------------------------------------- cursor, groups, mmr, bounds

/** The hits after the cursor record in the result order; none when no candidate has the cursor key. */
function after(ranked: Hit[], cursor: Json): Hit[] {
  for (let position = 0; position < ranked.length; position++) {
    if (sameKey(ranked[position].key, cursor)) return ranked.slice(position + 1);
  }
  return [];
}

function sameKey(key: string | number, cursor: Json): boolean {
  if (typeof key === "string") return typeof cursor === "string" && key === cursor;
  if (isNumber(cursor)) return key === cursor;
  const text = String(cursor).trim();
  return NUMBER.test(text) && Number(text) === key;
}

function within(score: number | null, bounds: Obj): boolean {
  if (score === null) return true;
  const low = bounds.min;
  const high = bounds.max;
  return (!isNumber(low) || score >= low) && (!isNumber(high) || score <= high);
}

/**
 * Groups in the order of their best hit, limit and offset counting groups, `size` hits each (1 by default); a record without
 * the group field belongs to the group null; hits outside the bounds are dropped, and so is a group left empty.
 */
function groups(ranked: Hit[], spec: Obj, bounds: Obj, keyField: string, offset: number, limit: number | null): Json[] {
  const group = spec.group as Obj;
  const size = isNumber(group.size) ? group.size : 1;
  const members = new Map<string, Hit[]>();
  const values = new Map<string, Json>();
  for (const hit of ranked) {
    const groupValue = path(hit.fields, list(group.field) as string[]);
    const identity = canonical(groupValue);
    if (!members.has(identity)) {
      members.set(identity, []);
      values.set(identity, groupValue);
    }
    (members.get(identity) as Hit[]).push(hit);
  }
  const leaders = [...members.keys()].slice(offset, limit === null ? undefined : offset + limit);
  const result: Json[] = [];
  for (const identity of leaders) {
    const kept = (members.get(identity) as Hit[]).slice(0, size).filter((hit) => within(hit.score, bounds))
      .map((hit) => project(hit, spec, keyField));
    if (kept.length > 0) result.push({ group: values.get(identity) as Json, hits: kept });
  }
  return result;
}

/** The digits and exponent of a number's shortest round-trip text: x = digits * 10^exponent. */
function decimal(x: number): [bigint, number] {
  const text = String(x);
  const match = /^(-?)([0-9]*)(?:\.([0-9]*))?(?:e([+-]?[0-9]+))?$/.exec(text) as RegExpExecArray;
  const fraction = match[3] ?? "";
  const digits = BigInt(match[1] + (match[2] + fraction));
  return [digits, Number(match[4] ?? "0") - fraction.length];
}

/** 1 - x in decimal arithmetic, so that 1 - 0.7 is 0.3. */
function complement(x: number): number {
  const [digits, exponent] = decimal(x);
  if (exponent >= 0) return 1 - x;
  const scale = 10n ** BigInt(-exponent);
  const rest = scale - digits;
  const negative = rest < 0n;
  const text = (negative ? -rest : rest).toString().padStart(-exponent + 1, "0");
  return Number((negative ? "-" : "") + text.slice(0, text.length + exponent) + "." + text.slice(text.length + exponent));
}

/**
 * Maximal marginal relevance: from the pool, pick the hit maximizing lambda * relevance - (1 - lambda) *
 * its highest similarity to a picked hit, the earlier rank breaking ties, until limit plus offset; each hit keeps its score.
 */
function diverse(ranked: Hit[], mmr: Obj, offset: number, limit: number | null): Hit[] {
  const fetch = offset + (limit === null ? ranked.length : limit);
  const size = isNumber(mmr.candidates) ? Math.max(mmr.candidates, fetch) : Math.max(10 * fetch, 10);
  const field = mmr.vectorField;
  const metric = mmr.metric;
  if (typeof field !== "string" || typeof metric !== "string") throw new Error("mmr needs the diversity vector field and its metric");
  const pool = ranked.filter((hit) => given(hit.vectors[field])).slice(0, size);
  const lambda = Number(mmr.lambda);
  const rest = complement(lambda);
  const penalty = pool.map(() => 0);
  const taken = pool.map(() => false);
  const picked: Hit[] = [];
  while (picked.length < fetch) {
    let best = -1;
    let bestValue = 0;
    pool.forEach((hit, i) => {
      if (!taken[i]) {
        const candidateValue = lambda * (hit.score as number) - rest * penalty[i];
        if (best < 0 || candidateValue > bestValue) {
          best = i;
          bestValue = candidateValue;
        }
      }
    });
    if (best < 0) break;
    taken[best] = true;
    const chosen = pool[best];
    pool.forEach((hit, i) => {
      if (!taken[i]) {
        const similar = similarity(hit.vectors[field], chosen.vectors[field], metric);
        penalty[i] = picked.length === 0 ? similar : Math.max(penalty[i], similar);
      }
    });
    picked.push(chosen);
  }
  return picked.slice(offset);
}

function bits(item: Json): number[] {
  if (typeof item === "string") {
    if (!/^[01]*$/.test(item)) throw new Error("a bit vector string holds only 0 and 1");
    return Array.from(item, Number);
  }
  if (!Array.isArray(item) || !item.every(isNumber)) throw new Error("a stored vector is a list of numbers or a bit string");
  return item as number[];
}

/** The canonical similarity of two stored vectors under the diversity field's metric. */
function similarity(a: Json, b: Json, metric: string): number {
  const x = bits(a);
  const y = bits(b);
  if (x.length !== y.length) throw new Error("mmr compares vectors of one dimension");
  if (metric === "cosine") {
    let dot = 0;
    let normX = 0;
    let normY = 0;
    for (let i = 0; i < x.length; i++) {
      dot += x[i] * y[i];
      normX += x[i] * x[i];
      normY += y[i] * y[i];
    }
    const norm = Math.sqrt(normX * normY);
    return norm !== 0 ? dot / norm : 0;
  }
  let total = 0;
  if (metric === "dot") {
    for (let i = 0; i < x.length; i++) total += x[i] * y[i];
    return total;
  }
  if (metric === "euclidean") {
    for (let i = 0; i < x.length; i++) total += (x[i] - y[i]) * (x[i] - y[i]);
    return -Math.sqrt(total);
  }
  if (metric === "manhattan") {
    for (let i = 0; i < x.length; i++) total += Math.abs(x[i] - y[i]);
    return -total;
  }
  if (metric === "hamming") {
    for (let i = 0; i < x.length; i++) if ((x[i] !== 0) !== (y[i] !== 0)) total += 1;
    return -total;
  }
  if (metric === "jaccard") {
    let both = 0;
    let either = 0;
    for (let i = 0; i < x.length; i++) {
      if (x[i] !== 0 && y[i] !== 0) both += 1;
      if (x[i] !== 0 || y[i] !== 0) either += 1;
    }
    return either !== 0 ? both / either : 0;
  }
  throw new Error(`unknown metric ${metric}`);
}

// ---------------------------------------------------------------- boosts

/** Each hit's score becomes its relevance with the combined boost applied; a hit no function applies to keeps it. */
function boost(hits: Hit[], block: Obj): void {
  const functions = list(block.functions) as Obj[];
  const combine = typeof block.combine === "string" ? block.combine : "multiply";
  const mode = typeof block.apply === "string" ? block.apply : "multiply";
  for (const hit of hits) {
    const present = functions.map((fn) => functionValue(hit.fields, fn)).filter((v): v is number => v !== null);
    if (present.length === 0) continue;
    let combined: number;
    if (combine === "sum") {
      combined = total(present);
    } else if (combine === "multiply") {
      combined = 1;
      for (const v of present) combined *= v;
    } else if (combine === "max") {
      combined = present.reduce((a, b) => (b > a ? b : a));
    } else if (combine === "avg") {
      combined = total(present) / present.length;
    } else if (combine === "replace") {
      combined = present[0];
    } else {
      throw new Error(`unknown boost combination ${combine}`);
    }
    hit.score = applied(mode, hit.score as number, combined);
  }
}

function total(values: number[]): number {
  let sum = 0;
  for (const v of values) sum += v;
  return sum;
}

function applied(mode: string, relevance: number, boostValue: number): number {
  if (mode === "sum") return relevance + boostValue;
  if (mode === "multiply") return relevance * boostValue;
  if (mode === "max") return boostValue > relevance ? boostValue : relevance;
  if (mode === "avg") return (relevance + boostValue) / 2;
  if (mode === "replace") return boostValue;
  throw new Error(`unknown boost application ${mode}`);
}

/**
 * One boost function: the weighted field value, the weighted decay of the field's distance from the origin, or the weight;
 * null where its field is null or its condition is not true.
 */
function functionValue(fields: Obj, fn: Obj): number | null {
  if (isObject(fn.when) && test(fields, fn.when) !== true) return null;
  const weight = isNumber(fn.weight) ? fn.weight : 1;
  if (fn.kind === "condition") return weight;
  const fieldValue = path(fields, list(fn.field) as string[]);
  if (fieldValue === null) return null;
  if (fn.kind === "field_value") {
    if (!isNumber(fieldValue)) throw new Error(`a field_value boost on a value that is not a number: ${canonical(fieldValue)}`);
    return weight !== 1 ? weight * fieldValue : fieldValue;
  }
  if (fn.kind !== "decay") throw new Error(`unknown boost kind ${String(fn.kind)}`);
  const rate = isNumber(fn.rate) ? fn.rate : 0.5;
  let distance: number;
  let scale: number;
  let shift: number;
  if (typeof fn.origin === "string") {
    distance = Math.abs(epoch(fieldValue) - epoch(fn.origin));
    scale = seconds(fn.scale ?? null);
    shift = given(fn.offset) ? seconds(fn.offset) : 0;
  } else {
    if (!isNumber(fieldValue)) throw new Error(`a decay boost on a value that is not a number: ${canonical(fieldValue)}`);
    distance = Math.abs(fieldValue - Number(fn.origin));
    scale = Number(fn.scale);
    shift = given(fn.offset) ? Number(fn.offset) : 0;
  }
  const d = Math.max(distance - shift, 0) / scale;
  let decay: number;
  if (fn.shape === "gauss") {
    decay = Math.pow(rate, Math.pow(d, 2));
  } else if (fn.shape === "exp") {
    decay = Math.pow(rate, d);
  } else if (fn.shape === "linear") {
    decay = Math.max(1 - d * complement(rate), 0);
  } else {
    throw new Error(`unknown decay shape ${String(fn.shape)}`);
  }
  return weight !== 1 ? weight * decay : decay;
}

// ---------------------------------------------------------------- conditions

/** A boost condition in three-valued logic, as SQL evaluates it: null where a compared value is missing. */
function test(fields: Obj, condition: Obj): boolean | null {
  if (Array.isArray(condition.and)) {
    const parts = condition.and.map((c) => test(fields, c as Obj));
    return parts.includes(false) ? false : parts.includes(null) ? null : true;
  }
  if (Array.isArray(condition.or)) {
    const parts = condition.or.map((c) => test(fields, c as Obj));
    return parts.includes(true) ? true : parts.includes(null) ? null : false;
  }
  if (isObject(condition.not)) return test(fields, condition.not) !== true;
  const op = String(condition.op);
  const fieldValue = path(fields, list(condition.field) as string[]);
  const operand = condition.value ?? null;
  if (op === "is_null" || op === "not_exists") return fieldValue === null;
  if (op === "is_not_null" || op === "exists") return fieldValue !== null;
  if (op === "neq") {
    if (fieldValue === null || operand === null) return fieldValue !== null || operand !== null;
    return canonical(fieldValue) !== canonical(operand);
  }
  if (op === "not_in") return member(fieldValue, operand) !== true;
  if (fieldValue === null || (operand === null && op !== "is_empty")) return null;
  if (op === "eq") return canonical(fieldValue) === canonical(operand);
  if (op === "gt" || op === "gte" || op === "lt" || op === "lte") return ordered(op, fieldValue, operand);
  if (op === "between") {
    const upper = condition.upper ?? null;
    const low = ordered("gte", fieldValue, operand);
    const high = upper === null ? null : ordered("lte", fieldValue, upper);
    return low === false || high === false ? false : low === null || high === null ? null : true;
  }
  if (op === "in") return member(fieldValue, operand);
  if (op === "contains") {
    if (Array.isArray(fieldValue)) return fieldValue.some((item) => canonical(item) === canonical(operand));
    return typeof fieldValue === "string" && typeof operand === "string" ? fieldValue.includes(operand) : null;
  }
  if (op === "contains_any" || op === "contains_all") {
    if (!Array.isArray(fieldValue) || !Array.isArray(operand)) return null;
    const held = new Set(fieldValue.map(canonical));
    const found = operand.map((item) => held.has(canonical(item)));
    return op === "contains_any" ? found.some(Boolean) : found.every(Boolean);
  }
  if (op === "like" || op === "prefix" || op === "contains_text") {
    if (typeof fieldValue !== "string" || typeof operand !== "string") return null;
    if (op === "prefix") return fieldValue.startsWith(operand);
    return op === "contains_text" ? fieldValue.includes(operand) : like(fieldValue, operand);
  }
  if (op === "is_empty") {
    if (Array.isArray(fieldValue)) return fieldValue.length === 0;
    return typeof fieldValue === "string" ? fieldValue.length === 0 : null;
  }
  if (op.startsWith("length_")) {
    if (Array.isArray(fieldValue)) return ordered(op.slice(7), fieldValue.length, operand);
    return typeof fieldValue === "string" ? ordered(op.slice(7), Array.from(fieldValue).length, operand) : null;
  }
  throw new Error(`unknown condition operator ${op}`);
}

function member(fieldValue: Json, operand: Json): boolean | null {
  if (fieldValue === null || !Array.isArray(operand)) return null;
  return operand.some((item) => canonical(fieldValue) === canonical(item));
}

function ordered(op: string, fieldValue: Json, operand: Json): boolean | null {
  if (rank(fieldValue) !== rank(operand) || rank(fieldValue) === 3) return null;
  const c = compareValues(fieldValue, operand);
  const outcomes: Record<string, boolean> = { eq: c === 0, neq: c !== 0, gt: c > 0, gte: c >= 0, lt: c < 0, lte: c <= 0 };
  return outcomes[op];
}

/** SQL LIKE: % matches any sequence, _ one character, a backslash escapes the next character. */
function like(text: string, pattern: string): boolean {
  const chars = Array.from(text);
  const symbols = Array.from(pattern);
  const tokens: Array<[string, string]> = [];
  for (let i = 0; i < symbols.length; i++) {
    const c = symbols[i];
    if (c === "\\" && i + 1 < symbols.length) {
      tokens.push(["char", symbols[i + 1]]);
      i += 1;
    } else {
      tokens.push(c === "%" ? ["any", ""] : c === "_" ? ["one", ""] : ["char", c]);
    }
  }
  let reach = [true, ...chars.map(() => false)];
  for (const [kind, char] of tokens) {
    if (kind === "any") {
      for (let j = 1; j <= chars.length; j++) reach[j] = reach[j] || reach[j - 1];
    } else {
      reach = [false, ...chars.map((c, j) => reach[j] && (kind === "one" || c === char))];
    }
  }
  return reach[chars.length];
}

// ---------------------------------------------------------------- aggregations

function aggregationName(a: Obj): string {
  return typeof a.name === "string" && a.name !== "" ? a.name : String(a.kind) + "_" + (list(a.field) as string[]).join("_");
}

/** The non-null values of a field over the hits; a list value contributes its elements. */
function valuesOf(hits: Hit[], segments: string[]): Json[] {
  const result: Json[] = [];
  for (const hit of hits) {
    const fieldValue = path(hit.fields, segments);
    for (const item of Array.isArray(fieldValue) ? fieldValue : [fieldValue]) {
      if (item !== null) result.push(item);
    }
  }
  return result;
}

function numbers(values: Json[], kind: string): number[] {
  for (const item of values) {
    if (!isNumber(item)) throw new Error(`the ${kind} aggregation over a value that is not a number: ${canonical(item)}`);
  }
  return values as number[];
}

function aggregate(hits: Hit[], a: Obj): Json {
  const kind = String(a.kind);
  const values = valuesOf(hits, list(a.field) as string[]);
  if (kind === "count") return values.length;
  if (kind === "distinct_count" || kind === "cardinality") return new Set(values.map(canonical)).size;
  if (kind === "min" || kind === "max") {
    if (values.length === 0) return null;
    let best = values[0];
    for (const item of values.slice(1)) {
      const c = compareValues(item, best);
      if (kind === "min" ? c < 0 : c > 0) best = item;
    }
    return best;
  }
  if (kind === "sum" || kind === "avg" || kind === "stats") {
    const found = numbers(values, kind);
    const sum = found.length > 0 ? total(found) : null;
    const average = sum === null ? null : sum / found.length;
    if (kind === "sum") return sum;
    if (kind === "avg") return average;
    return {
      count: found.length,
      min: found.length > 0 ? found.reduce((x, y) => (y < x ? y : x)) : null,
      max: found.length > 0 ? found.reduce((x, y) => (y > x ? y : x)) : null,
      avg: average,
      sum,
    };
  }
  if (kind === "terms" || kind === "facet") {
    const counts = new Map<string, [Json, number]>();
    for (const item of values) {
      const identity = canonical(item);
      const entry = counts.get(identity);
      if (entry === undefined) counts.set(identity, [item, 1]);
      else entry[1] += 1;
    }
    const size = isNumber(a.size) ? a.size : 10;
    return [...counts.values()].sort((x, y) => y[1] - x[1] || compareValues(x[0], y[0])).slice(0, size)
      .map(([key, count]) => ({ key, count }));
  }
  if (kind === "histogram") {
    const interval = intervalNumber(a.interval ?? null);
    return buckets(numbers(values, kind).map((v) => Math.floor(v / interval) * interval), null);
  }
  if (kind === "date_histogram") {
    const interval = seconds(a.interval ?? null);
    return buckets(values.map((v) => Math.floor(epoch(v) / interval) * interval), timestamp);
  }
  if (kind === "percentiles") {
    const sorted = [...numbers(values, kind)].sort((x, y) => x - y);
    const result: Obj = {};
    for (const p of PERCENTS) result[String(p)] = percentile(sorted, p / 100);
    return result;
  }
  throw new Error(`unknown aggregation kind ${kind}`);
}

function buckets(keys: number[], label: ((key: number) => string) | null): Json[] {
  const counts = new Map<number, number>();
  for (const key of keys) counts.set(key, (counts.get(key) ?? 0) + 1);
  return [...counts.keys()].sort((x, y) => x - y).map((key) => ({ key: label === null ? key : label(key), count: counts.get(key) as number }));
}

/** percentile_cont: linear interpolation between the closest ranks. */
function percentile(sorted: number[], fraction: number): number | null {
  if (sorted.length === 0) return null;
  const position = fraction * (sorted.length - 1);
  const low = Math.floor(position);
  const high = Math.min(low + 1, sorted.length - 1);
  return sorted[low] + (sorted[high] - sorted[low]) * (position - low);
}

function intervalNumber(interval: Json): number {
  if (isNumber(interval) && interval > 0) return interval;
  if (typeof interval === "string" && NUMBER.test(interval.trim()) && Number(interval) > 0) return Number(interval);
  throw new Error("a histogram without a numeric interval");
}

// ---------------------------------------------------------------- time

/** An interval such as 1d, 12h or 1 day 6 hours, in seconds (PostgreSQL interval units of fixed length). */
function seconds(interval: Json): number {
  if (isNumber(interval) && interval > 0) return interval;
  if (typeof interval !== "string") throw new Error("an interval is a string such as 1d or 12h");
  const text = interval.trim();
  let sum = 0;
  let position = 0;
  while (position < text.length) {
    INTERVAL.lastIndex = position;
    const match = INTERVAL.exec(text);
    if (match === null || !(match[2].toLowerCase() in UNITS)) {
      throw new Error(`an interval of numbers with the units ms, s, m, h, d or w: ${interval}`);
    }
    sum += Number(match[1]) * UNITS[match[2].toLowerCase()];
    position = INTERVAL.lastIndex;
    while (position < text.length && text[position] === " ") position += 1;
  }
  if (!(sum > 0)) throw new Error(`an interval of numbers with the units ms, s, m, h, d or w: ${interval}`);
  return sum;
}

function floorDiv(a: number, b: number): number {
  return Math.floor(a / b);
}

/** Days since 1970-01-01 of a proleptic Gregorian date. */
function days(year: number, month: number, day: number): number {
  const y = year - (month <= 2 ? 1 : 0);
  const era = floorDiv(y, 400);
  const yoe = y - era * 400;
  const doy = floorDiv(153 * (month + (month > 2 ? -3 : 9)) + 2, 5) + day - 1;
  const doe = yoe * 365 + floorDiv(yoe, 4) - floorDiv(yoe, 100) + doy;
  return era * 146097 + doe - 719468;
}

/** Seconds since the epoch of an ISO 8601 timestamp (UTC unless it carries an offset), of now, or of a number of seconds. */
function epoch(item: Json): number {
  if (isNumber(item)) return item;
  if (item === "now") return Date.now() / 1000;
  const match = typeof item === "string" ? TIMESTAMP.exec(item) : null;
  if (match === null) throw new Error(`a timestamp in ISO 8601 form: ${canonical(item)}`);
  const [year, month, day] = [Number(match[1]), Number(match[2]), Number(match[3])];
  const [hour, minute, second] = [match[4], match[5], match[6]].map((part) => (part === undefined ? 0 : Number(part)));
  if (!(month >= 1 && month <= 12 && day >= 1 && day <= 31 && hour < 24 && minute < 60 && second < 60)) {
    throw new Error(`a timestamp in ISO 8601 form: ${String(item)}`);
  }
  let result = days(year, month, day) * 86400 + hour * 3600 + minute * 60 + second + Number("0" + (match[7] ?? ""));
  const zone = match[8];
  if (zone !== undefined && zone !== "Z" && zone !== "z") {
    const digits = zone.slice(1).replace(":", "");
    const shift = Number(digits.slice(0, 2)) * 3600 + (digits.length > 2 ? Number(digits.slice(2, 4)) * 60 : 0);
    result -= zone[0] === "+" ? shift : -shift;
  }
  return result;
}

function pad(n: number, width: number): string {
  return String(n).padStart(width, "0");
}

/** A bin start as PostgreSQL prints a timestamp in JSON: 2026-11-16T12:00:00, with up to six fraction digits. */
function timestamp(secondsSinceEpoch: number): string {
  const micros = Math.floor(secondsSinceEpoch * 1_000_000 + 0.5);
  const dayCount = floorDiv(micros, 86_400_000_000);
  const rest = micros - dayCount * 86_400_000_000;
  const z = dayCount + 719468;
  const era = floorDiv(z, 146097);
  const doe = z - era * 146097;
  const yoe = floorDiv(doe - floorDiv(doe, 1460) + floorDiv(doe, 36524) - floorDiv(doe, 146096), 365);
  const doy = doe - (365 * yoe + floorDiv(yoe, 4) - floorDiv(yoe, 100));
  const mp = floorDiv(5 * doy + 2, 153);
  const day = doy - floorDiv(153 * mp + 2, 5) + 1;
  const month = mp + (mp < 10 ? 3 : -9);
  const year = yoe + era * 400 + (month <= 2 ? 1 : 0);
  const second = floorDiv(rest, 1_000_000);
  const fraction = rest - second * 1_000_000;
  const text = `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}T${pad(floorDiv(second, 3600), 2)}:${pad(floorDiv(second, 60) % 60, 2)}:${pad(second % 60, 2)}`;
  return text + (fraction !== 0 ? "." + pad(fraction, 6).replace(/0+$/, "") : "");
}

// ---------------------------------------------------------------- projection and values

/**
 * The hit object: key, score, the output fields in output order (all fields for `output *`) without the excluded ones, the
 * stored vectors with with-vectors, then the highlight and the explanation as the target gave them.
 */
function project(hit: Hit, spec: Obj, keyField: string): Obj {
  const excluded = new Set(list(spec.exclude) as string[]);
  const record: Obj = { [keyField]: hit.key };
  if (hit.score !== null) record.score = hit.score;
  const output = spec.output;
  const names = Array.isArray(output)
    ? (output as string[]).filter((name) => Object.prototype.hasOwnProperty.call(hit.fields, name))
    : Object.keys(hit.fields);
  for (const name of names) {
    if (name !== keyField && !excluded.has(name)) record[name] = hit.fields[name];
  }
  if (spec.withVectors === true) {
    for (const [name, vector] of Object.entries(hit.vectors)) {
      if (!excluded.has(name)) record[name] = vector;
    }
  }
  if (hit.highlight !== null) record.highlight = hit.highlight;
  if (hit.explanation !== null) record.explanation = hit.explanation;
  return record;
}

/** x rounded to six fraction digits, half to even on its exact binary value (Python's round). */
function rounded(x: number): number {
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, x);
  const high = view.getUint32(0);
  const exponentBits = (high >>> 20) & 0x7ff;
  let mantissa = (BigInt(high & 0xfffff) << 32n) | BigInt(view.getUint32(4));
  let exponent = -1074;
  if (exponentBits !== 0) {
    mantissa |= 1n << 52n;
    exponent = exponentBits - 1075;
  }
  if (exponent >= 0) return x;
  const numerator = mantissa * 10n ** BigInt(DIGITS);
  const denominator = 1n << BigInt(-exponent);
  let quotient = numerator / denominator;
  const twice = (numerator % denominator) * 2n;
  if (twice > denominator || (twice === denominator && (quotient & 1n) === 1n)) quotient += 1n;
  const digits = quotient.toString().padStart(DIGITS + 1, "0");
  return Number((x < 0 ? "-" : "") + digits.slice(0, -DIGITS) + "." + digits.slice(-DIGITS));
}

/** Result values in one form for every host language: floats rounded to six digits, integral values without a fraction. */
function value(item: Json): Json {
  if (isNumber(item)) {
    if (!Number.isFinite(item)) return item;
    return rounded(item) + 0;
  }
  if (Array.isArray(item)) return item.map(value);
  if (isObject(item)) {
    const result: Obj = {};
    for (const [key, entry] of Object.entries(item)) result[key] = value(entry);
    return result;
  }
  return item;
}
